EXT_PARAMS = [
    ("accept","application/octet-stream"),
    ("accept","application/json"),
    ("encoding","gzip"),
    ("timeout","1"),
]

SAFE_CHARS = string.ascii_letters + string.digits + "-._~"


def rand_choice(rnd: random.Random, seq: List[str]) -> str:
    return seq[rnd.randrange(len(seq))]


def rand_label(rnd: random.Random, min_len=3, max_len=10) -> str:
    n = rnd.randint(min_len, max_len)
    return ''.join(rnd.choice(string.ascii_lowercase + string.digits) for _ in range(n))


def build_host(rnd: random.Random) -> str:
    if rnd.random() < 0.5:
        return rand_choice(rnd, HOSTS)
    # generate subdomain.host.tld
    labels = [rand_label(rnd) for _ in range(rnd.randint(2, 4))]
    tlds = ["com", "org", "net", "io", "local"]
    return ".".join(labels + [rand_choice(rnd, tlds)])


def build_path(rnd: random.Random) -> str:
    if rnd.random() < 0.6:
        return rand_choice(rnd, PATHS)
    segs = []
    count = rnd.randint(1, 5)
    for _ in range(count):
        segs.append(''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(1, 12))))
    # occasionally end with a well-known extension
    if rnd.random() < 0.5:
        ext = rand_choice(rnd, [".gsb", ".gtx", ".tif", ".json", ".wkt", ".xml", ".zip", ".pbf"])
        segs[-1] += ext
    return "/" + "/".join(segs)


def build_query(rnd: random.Random) -> str:
    pairs: List[Tuple[str,str]] = []
    # include common keys and random ones
    for _ in range(rnd.randint(0, 4)):
        k = rand_choice(rnd, QUERY_KEYS)
        v = ''.join(rnd.choice(SAFE_CHARS) for _ in range(rnd.randint(1, 10)))
        pairs.append((k, v))
    # possibly include parameters relevant to caching/ttl
    if rnd.random() < 0.7:
        k, v = rand_choice(rnd, EXT_PARAMS)
        pairs.append((k, v))
    if not pairs:
        return ""
    return "?" + "&".join(f"{k}={v}" for k, v in pairs)


def build_fragment(rnd: random.Random) -> str:
    if rnd.random() < 0.3:
        return "#" + rand_choice(rnd, FRAGMENTS)
    return ""


def build_http_url(rnd: random.Random) -> str:
    scheme = rand_choice(rnd, ["http", "https"]) if rnd.random() < 0.85 else rand_choice(rnd, SCHEMES)
    host = build_host(rnd)
    path = build_path(rnd)
    query = build_query(rnd)
    frag = build_fragment(rnd)
    return f"{scheme}://{host}{path}{query}{frag}"


def build_file_path(rnd: random.Random) -> str:
    prefix = rand_choice(rnd, FILE_PREFIXES)
    # ensure directory structure variety
    dirs = []
    for _ in range(rnd.randint(0, 3)):
        dirs.append(rand_label(rnd))
    name = rand_choice(rnd, FILE_NAMES)
    path = prefix + ("/".join(dirs) + ("/" if dirs else "")) + name
    # normalize slashes for Windows prefix examples
    if prefix.startswith("C:"):
        path = path.replace("/", "\\")
    return path


def build_file_url(rnd: random.Random) -> str:
    p = build_file_path(rnd)
    if p.startswith("C:"):
        # file URL for Windows path
        return "file:///" + p.replace("\\", "/")
    else:
        return "file://" + p


def build_identifier_code(rnd: random.Random) -> str:
    # Arbitrary string, but keep it short and meaningful
    if rnd.random() < 0.5:
        return f"EPSG:{rnd.randint(1, 100000)}"
    return ''.join(rnd.choice(string.ascii_uppercase + string.digits + "-_.:") for _ in range(rnd.randint(3, 20)))


def pick_buffer_variant(rnd: random.Random) -> bytes:
    # Choose among: HTTP(S) URL, file URL, plain file path, or identifier code.
    r = rnd.random()
    if r < 0.45:
        s = build_http_url(rnd)
    elif r < 0.65:
        s = build_file_url(rnd)
    elif r < 0.9:
        s = build_file_path(rnd)
    else:
        s = build_identifier_code(rnd)
    b = s.encode('utf-8', errors='strict')
    # Ensure total length under 4096 and NUL-terminated string for C APIs
    if len(b) > 4094:
        b = b[:4094]
    return b + b"\x00"


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Optionally concatenate multiple candidates separated by NUL to feed successive FUZZ_PARAM_STR/FILENAME calls
    # However, many fuzz harnesses consume input sequentially; provide a single strong candidate.
    return pick_buffer_variant(rnd)
